insert into pensum_temas (id, episodio, orden, nombre_es, nombre_en, descripcion) values
  ('ep8-reflexivos', 8, 8, $t$Pronombres reflexivos intensivos$t$, $t$Intensifying reflexive pronouns$t$, $t$Myself, yourself, himself… para dar énfasis o decir que alguien lo hizo solo: I did it myself.$t$),
  ('ep8-invitaciones', 8, 9, $t$Invitaciones: would, may y do$t$, $t$Making and answering invitations$t$, $t$Invitar con would like, may y do; aceptar o rechazar con cortesía.$t$)
insert into lecciones (id, materia_id, unidad_id, episodio, orden, tipo, titulo, descripcion) values
  ('ep8-reflexivos', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 5, 'tema', $t$Pronombres reflexivos: yo mismo$t$, $t$Myself, yourself, himself, herself, ourselves, themselves para dar énfasis (Unidad 16).$t$),
  ('ep8-invitaciones', 'ingles', (select id from unidades where materia_id = 'ingles' and numero = 16), 8, 6, 'tema', $t$Invitar y responder: would, may, do$t$, $t$Invitar y aceptar o rechazar con would like, may y do (Now I Can de la Unidad 16).$t$)
insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values
  ('ep8-reflexivos-01', 'ep8-reflexivos', 1, 'elegir', $j${"frase":"I made this cake ___.","opciones":["myself","me","I"],"correcta":0,"es":"Hice este pastel yo mismo.","explicacion":"Pronombre intensivo: myself = yo mismo."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-02', 'ep8-reflexivos', 2, 'elegir', $j${"frase":"The boss ___ called the client.","opciones":["himself","hisself","herself"],"correcta":0,"es":"El jefe mismo llamó al cliente.","explicacion":"Para un hombre: himself."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-03', 'ep8-reflexivos', 3, 'elegir', $j${"frase":"The children washed the car ___.","opciones":["theirselves","themselves","themself"],"correcta":1,"es":"Los niños lavaron el carro ellos mismos.","explicacion":"Plural: themselves."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-04', 'ep8-reflexivos', 4, 'elegir', $j${"frase":"We painted the house ___.","opciones":["ourselves","us","ourself"],"correcta":0,"es":"Pintamos la casa nosotros mismos.","explicacion":"Plural de nosotros: ourselves."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-05', 'ep8-reflexivos', 5, 'escribir', $j${"respuestas":["i did it myself","i did it myself."],"mostrar":"I did it myself.","es":"Lo hice yo mismo.","explicacion":"Dar énfasis: myself."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-06', 'ep8-reflexivos', 6, 'ordenar', $j${"frase":"She cooked dinner herself .","es":"Ella cocinó la cena ella misma.","explicacion":"Sujeto + verbo + objeto + herself."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-07', 'ep8-reflexivos', 7, 'emparejar', $j${"pares":[["myself","yo mismo"],["yourself","tú mismo"],["himself","él mismo"],["herself","ella misma"]],"es":"","explicacion":"Pronombre reflexivo intensivo según la persona."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('ep8-reflexivos-08', 'ep8-reflexivos', 8, 'escuchar', $j${"opciones":["She cooked it herself.","She bought it.","Someone else cooked it."],"correcta":0,"audio":"She cooked it herself.","es":"Ella lo cocinó ella misma.","explicacion":"Herself = ella misma."}$j$::jsonb, 'ep8-reflexivos', 'estudio', false),
  ('banco-ep8-ep8-reflexivos-01', 'banco-ep8', 1, 'comprension', $j${"modo":"leer","lineas":[{"en":"Tom: Did you paint the wall?","es":"Tom: ¿Pintaste la pared?"},{"en":"Ana: Yes, I did it myself.","es":"Ana: Sí, la pinté yo misma."}],"pregunta":"Who painted the wall?","pregunta_es":"¿Quién pintó la pared?","opciones":["Ana herself","Tom","A friend"],"correcta":0,"explicacion":"I did it myself = yo misma."}$j$::jsonb, 'ep8-reflexivos', 'input', false),
  ('banco-ep8-ep8-reflexivos-02', 'banco-ep8', 2, 'comprension', $j${"modo":"leer","lineas":[{"en":"Carlos: Who cooks dinner at your house?","es":"Carlos: ¿Quién cocina la cena en tu casa?"},{"en":"Marta: We cook it ourselves, every night.","es":"Marta: La cocinamos nosotros mismos, cada noche."}],"pregunta":"Who cooks dinner in Marta's house?","pregunta_es":"¿Quién cocina la cena en casa de Marta?","opciones":["Marta and her family","A restaurant","Carlos alone"],"correcta":0,"explicacion":"We cook it ourselves = ellos mismos en familia."}$j$::jsonb, 'ep8-reflexivos', 'input', false),
  ('banco-ep8-ep8-reflexivos-03', 'banco-ep8', 3, 'decir', $j${"es":"Lo hice yo mismo.","respuestas":["i did it myself","i did it myself."],"mostrar":"I did it myself.","explicacion":"Didn't need help: myself."}$j$::jsonb, 'ep8-reflexivos', 'output', false),
  ('banco-ep8-ep8-reflexivos-04', 'banco-ep8', 4, 'decir', $j${"es":"Ellos mismos lo arreglaron.","respuestas":["they fixed it themselves","they repaired it themselves"],"mostrar":"They fixed it themselves.","explicacion":"Themselves para plural."}$j$::jsonb, 'ep8-reflexivos', 'output', false),
  ('banco-ep8-ep8-reflexivos-05', 'banco-ep8', 5, 'libre', $j${"pregunta":"Write two sentences about something you did yourself this year. Use myself or ourselves.","pregunta_es":"Escribe dos frases sobre algo que hiciste tú mismo este año. Usa myself u ourselves.","ejemplo":"I learned English myself."}$j$::jsonb, 'ep8-reflexivos', 'output', false),
  ('banco-ep8-ep8-reflexivos-06', 'banco-ep8', 6, 'rapido', $j${"frase":"I cooked it ___.","opciones":["myself","me"],"correcta":0,"es":"Lo cociné yo mismo.","explicacion":"myself.","segundos":6}$j$::jsonb, 'ep8-reflexivos', 'fluidez', false),
  ('banco-ep8-ep8-reflexivos-07', 'banco-ep8', 7, 'rapido', $j${"frase":"We built the shelf ___.","opciones":["ourselves","us"],"correcta":0,"es":"Construimos el estante nosotros mismos.","explicacion":"ourselves.","segundos":6}$j$::jsonb, 'ep8-reflexivos', 'fluidez', false),
  ('banco-ep8-ep8-reflexivos-08', 'banco-ep8', 8, 'rapido', $j${"frase":"You should see it ___.","opciones":["yourself","your"],"correcta":0,"es":"Deberías verlo tú mismo.","explicacion":"yourself.","segundos":6}$j$::jsonb, 'ep8-reflexivos', 'fluidez', false),
  ('examen-ep8-ep8-reflexivos-01', 'examen-ep8', 1, 'elegir', $j${"frase":"She taught ___ English.","opciones":["herself","her","she"],"correcta":0,"es":"Ella se enseñó inglés sola.","explicacion":"herself = ella misma."}$j$::jsonb, 'ep8-reflexivos', 'estudio', true),
  ('examen-ep8-ep8-reflexivos-02', 'examen-ep8', 2, 'elegir', $j${"frase":"They built the house ___.","opciones":["themselves","theirselves","them"],"correcta":0,"es":"Ellos construyeron la casa ellos mismos.","explicacion":"themselves."}$j$::jsonb, 'ep8-reflexivos', 'estudio', true),
  ('examen-ep8-ep8-reflexivos-03', 'examen-ep8', 3, 'escribir', $j${"respuestas":["i fixed it myself","i fixed it myself."],"mostrar":"I fixed it myself.","es":"Lo arreglé yo mismo.","explicacion":"myself."}$j$::jsonb, 'ep8-reflexivos', 'estudio', true),
  ('ep8-invitaciones-01', 'ep8-invitaciones', 1, 'elegir', $j${"frase":"___ you like a drink?","opciones":["Would","Do","May"],"correcta":0,"es":"¿Te gustaría tomar algo?","explicacion":"Would you like… = invitación cortés."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-02', 'ep8-invitaciones', 2, 'elegir', $j${"frase":"___ I offer you a coffee?","opciones":["Would","May","Do"],"correcta":1,"es":"¿Puedo ofrecerte un café?","explicacion":"May I offer… = forma formal."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-03', 'ep8-invitaciones', 3, 'elegir', $j${"frase":"Do you want to ___ lunch with me tomorrow?","opciones":["have","to have","having"],"correcta":0,"es":"¿Quieres almorzar conmigo mañana?","explicacion":"Do you want to + verbo base."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-04', 'ep8-invitaciones', 4, 'elegir', $j${"frase":"Thanks, that ___ great!","opciones":["sounds","is","looks"],"correcta":0,"es":"¡Gracias, suena genial!","explicacion":"That sounds great = acepto."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-05', 'ep8-invitaciones', 5, 'escribir', $j${"respuestas":["would you like to go to the movies","would you like to go to the movies?"],"mostrar":"Would you like to go to the movies?","es":"¿Te gustaría ir al cine?","explicacion":"Would you like to + verbo."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-06', 'ep8-invitaciones', 6, 'ordenar', $j${"frase":"May I invite you to lunch on Friday ?","es":"¿Puedo invitarte a almorzar el viernes?","explicacion":"May I invite you… = invitación formal."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-07', 'ep8-invitaciones', 7, 'emparejar', $j${"pares":[["Would you like…?","¿Te gustaría…?"],["May I invite you…?","¿Puedo invitarte…?"],["That sounds great.","Suena genial."],["I'm sorry, I'm busy.","Lo siento, estoy ocupado."]],"es":"","explicacion":"Invitar, aceptar y rechazar con cortesía."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('ep8-invitaciones-08', 'ep8-invitaciones', 8, 'escuchar', $j${"opciones":["Offer food","Ask about the car","Say goodbye"],"correcta":0,"audio":"Would you like something to eat?","es":"¿Te gustaría algo de comer?","explicacion":"Oferta de comida."}$j$::jsonb, 'ep8-invitaciones', 'estudio', false),
  ('banco-ep8-ep8-invitaciones-01', 'banco-ep8', 1, 'comprension', $j${"modo":"leer","lineas":[{"en":"Ana: Would you like to come to the party on Saturday?","es":"Ana: ¿Te gustaría venir a la fiesta el sábado?"},{"en":"Luis: I'm sorry, I can't. I'm working.","es":"Luis: Lo siento, no puedo. Estoy trabajando."}],"pregunta":"Can Luis go to the party?","pregunta_es":"¿Puede Luis ir a la fiesta?","opciones":["No, he is working.","Yes, he is free.","He does not know."],"correcta":0,"explicacion":"Rechaza porque trabaja."}$j$::jsonb, 'ep8-invitaciones', 'input', false),
  ('banco-ep8-ep8-invitaciones-02', 'banco-ep8', 2, 'comprension', $j${"modo":"leer","lineas":[{"en":"Sara: May I invite you for a coffee?","es":"Sara: ¿Puedo invitarte a un café?"},{"en":"Paul: Sure, I'd love to.","es":"Paul: Claro, me encantaría."}],"pregunta":"What does Paul say?","pregunta_es":"¿Qué dice Paul?","opciones":["He accepts.","He refuses.","He is late."],"correcta":0,"explicacion":"I'd love to = acepta."}$j$::jsonb, 'ep8-invitaciones', 'input', false),
  ('banco-ep8-ep8-invitaciones-03', 'banco-ep8', 3, 'decir', $j${"es":"¿Te gustaría un café?","respuestas":["would you like a coffee","would you like a coffee?"],"mostrar":"Would you like a coffee?","explicacion":"Would you like + sustantivo."}$j$::jsonb, 'ep8-invitaciones', 'output', false),
  ('banco-ep8-ep8-invitaciones-04', 'banco-ep8', 4, 'decir', $j${"es":"Gracias, suena genial.","respuestas":["thanks that sounds great","thanks, that sounds great","that sounds great"],"mostrar":"Thanks, that sounds great.","explicacion":"Aceptar con That sounds great."}$j$::jsonb, 'ep8-invitaciones', 'output', false),
  ('banco-ep8-ep8-invitaciones-05', 'banco-ep8', 5, 'libre', $j${"pregunta":"Invite a friend to do something this weekend. Use would like, may or do.","pregunta_es":"Invita a un amigo a hacer algo este fin de semana. Usa would like, may o do.","ejemplo":"Would you like to go for a walk on Sunday?"}$j$::jsonb, 'ep8-invitaciones', 'output', false),
  ('banco-ep8-ep8-invitaciones-06', 'banco-ep8', 6, 'rapido', $j${"frase":"Would you ___ a drink?","opciones":["like","likes"],"correcta":0,"es":"¿Te gustaría tomar algo?","explicacion":"would like.","segundos":6}$j$::jsonb, 'ep8-invitaciones', 'fluidez', false),
  ('banco-ep8-ep8-invitaciones-07', 'banco-ep8', 7, 'rapido', $j${"frase":"May I ___ you to dinner?","opciones":["invite","invites"],"correcta":0,"es":"¿Puedo invitarte a cenar?","explicacion":"may + verbo base.","segundos":6}$j$::jsonb, 'ep8-invitaciones', 'fluidez', false),
  ('banco-ep8-ep8-invitaciones-08', 'banco-ep8', 8, 'rapido', $j${"frase":"That sounds ___!","opciones":["great","greatly"],"correcta":0,"es":"¡Suena genial!","explicacion":"great = genial.","segundos":6}$j$::jsonb, 'ep8-invitaciones', 'fluidez', false),
  ('examen-ep8-ep8-invitaciones-01', 'examen-ep8', 1, 'elegir', $j${"frase":"I'm sorry, I ___ come. I have work.","opciones":["can't","don't","isn't"],"correcta":0,"es":"Lo siento, no puedo venir. Tengo trabajo.","explicacion":"can't = cannot."}$j$::jsonb, 'ep8-invitaciones', 'estudio', true),
  ('examen-ep8-ep8-invitaciones-02', 'examen-ep8', 2, 'elegir', $j${"frase":"___ I offer you some water?","opciones":["Would","May","Does"],"correcta":1,"es":"¿Puedo ofrecerte agua?","explicacion":"May I offer…"}$j$::jsonb, 'ep8-invitaciones', 'estudio', true),
  ('examen-ep8-ep8-invitaciones-03', 'examen-ep8', 3, 'escribir', $j${"respuestas":["would you like something to eat","would you like something to eat?"],"mostrar":"Would you like something to eat?","es":"¿Te gustaría comer algo?","explicacion":"Would you like something to eat?"}$j$::jsonb, 'ep8-invitaciones', 'estudio', true)
